#!/usr/bin/env python3
import sys


def solve(N, K, A):
    s = set()
    for a in A:
        for x in a:
            s.add(x)
    print(N - len(s))
    return

# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))
    K = int(next(tokens))
    A = [[] for _ in range(K)]
    for i in range(K):
        d = int(next(tokens))
        for j in range(d):
            A[i].append(int(next(tokens)))
    solve(N, K, A)

if __name__ == '__main__':
    main()
